288	    constructor() {
289	        effect(
290	            () => {
291	                const sectionId = this.settingsCtx.pendingScrollTarget();
292	                if (!sectionId || typeof document === 'undefined') {
293	                    return;
294	                }
295	
296	                const scrollRoot = this.scrollToSection(sectionId);
297	                this.schedulePendingScrollTargetClear(scrollRoot);
298	            },
299	            { injector: this.injector }
300	        );
301	
302	        effect(
303	            (onCleanup) => {
304	                const activeSectionId = this.activeSection();
305	                const activeSectionElement =
306	                    this.elementRef.nativeElement.querySelector(
307	                        `#${activeSectionId}`
308	                    ) as HTMLElement | null;
309	
310	                if (!activeSectionElement) {
311	                    return;
312	                }
313	
314	                const animation = activeSectionElement.animate(
315	                    [
316	                        {
317	                            boxShadow:
318	                                'inset 0 0 0 1px var(--settings-group-active-ring), 0 8px 18px -24px var(--settings-group-active-glow)',
319	                        },
320	                        {
321	                            boxShadow:
322	                                'inset 0 0 0 1px var(--settings-group-active-ring), 0 12px 22px -24px var(--settings-group-active-glow)',
323	                        },
324	                        {
325	                            boxShadow:
326	                                'inset 0 0 0 1px var(--settings-group-active-ring), 0 8px 18px -24px var(--settings-group-active-glow)',
327	                        },
328	                    ],
329	                    {
330	                        duration: 260,
331	                        easing: 'ease-out',
332	                    }
333	                );
334	
335	                onCleanup(() => animation.cancel());
336	            },
337	            { injector: this.injector }
338	        );
339	    }
