413	    /**
414	     * Sets the epg urls to the form array
415	     * @param epgUrls urls of the EPG sources
416	     */
417	    setEpgUrls(epgUrls: string[] | string): void {
418	        const URL_REGEX = /^(http|https|file):\/\/[^ "]+$/;
419	
420	        const urls = Array.isArray(epgUrls) ? epgUrls : [epgUrls];
421	        const filteredUrls = urls
422	            .map((url) => url.trim())
423	            .filter((url) => url !== '');
424	
425	        filteredUrls.forEach((url) => {
426	            this.epgUrl.push(
427	                new FormControl(url, [Validators.pattern(URL_REGEX)])
428	            );
429	        });
430	    }
