597	    exportData() {
598	        this.playlistsService
599	            .getAllData()
600	            .pipe(take(1))
601	            .subscribe((data) => {
602	                const blob = new Blob([JSON.stringify(data)], {
603	                    type: 'text/plain',
604	                });
605	                const url = window.URL.createObjectURL(blob);
606	                const link = document.createElement('a');
607	                link.href = url;
608	                link.download = 'playlists.json';
609	                link.click();
610	                window.URL.revokeObjectURL(url);
611	            });
