614	    importData() {
615	        const input = document.createElement('input');
616	        input.type = 'file';
617	        input.accept = 'application/json';
618	
619	        input.addEventListener('change', (event: Event) => {
620	            const target = event.target as HTMLInputElement;
621	            const file = target.files?.[0];
622	
623	            if (file) {
624	                const reader = new FileReader();
625	                reader.onload = () => {
626	                    const contents = reader.result;
627	
628	                    try {
629	                        const parsedPlaylists: Playlist[] = JSON.parse(
630	                            contents.toString()
631	                        );
632	
633	                        if (!Array.isArray(parsedPlaylists)) {
634	                            this.openSettingsSnackbar(
635	                                this.translate.instant('SETTINGS.IMPORT_ERROR'),
636	                            );
637	                        } else {
638	                            this.store.dispatch(
639	                                PlaylistActions.addManyPlaylists({
640	                                    playlists: parsedPlaylists,
641	                                })
642	                            );
643	                        }
644	                    } catch (error) {
645	                        this.openSettingsSnackbar(
646	                            this.translate.instant('SETTINGS.IMPORT_ERROR'),
647	                        );
648	                        console.error(error);
649	                    }
650	                };
651	                reader.readAsText(file);
652	            }
653	        });
654	
655	        input.click();
656	    }
