687	    private setupSectionObserver(): void {
688	        if (typeof IntersectionObserver === 'undefined') {
689	            return;
690	        }
691	
692	        const scrollRoot = this.getScrollRoot();
693	        const contentSections = Array.from(
694	            this.elementRef.nativeElement.querySelectorAll(
695	                '.settings-group[id]'
696	            )
697	        ) as HTMLElement[];
698	        const sections: ObservedSettingsSection[] = contentSections.map(
699	            (section) => ({
700	                id: section.id,
701	                element: section,
702	            })
703	        );
704	
705	        if (sections.length === 0) {
706	            return;
707	        }
708	
709	        this.sectionObserver?.disconnect();
710	        this.sectionObserver = new IntersectionObserver(
711	            () => {
712	                if (this.settingsCtx.pendingScrollTarget()) {
713	                    return;
714	                }
715	
716	                const activeSection = this.resolveActiveSection(sections);
717	                if (activeSection) {
718	                    this.settingsCtx.setActiveSection(activeSection);
719	                }
720	            },
721	            {
722	                root: scrollRoot,
723	                threshold: [0.12, 0.24, 0.4, 0.6],
724	                rootMargin: '-18% 0px -52% 0px',
725	            }
726	        );
727	
728	        sections.forEach((section) =>
729	            this.sectionObserver?.observe(section.element)
730	        );
731	
732	        const initialSection = this.resolveActiveSection(sections);
733	        if (initialSection) {
734	            this.settingsCtx.setActiveSection(initialSection);
735	        }
736	    }
737	
738	    private resolveActiveSection(
739	        sections: ObservedSettingsSection[]
740	    ): string | null {
741	        const scrollRoot = this.getScrollRoot();
742	        const rootTop = scrollRoot?.getBoundingClientRect().top ?? 0;
743	        const rootHeight = scrollRoot?.clientHeight ?? window.innerHeight;
744	        const activationLine = rootTop + Math.min(rootHeight * 0.28, 220);
745	        const sectionAtActivationLine = sections.find((section) => {
746	            const rect = section.element.getBoundingClientRect();
747	            return rect.top <= activationLine && rect.bottom >= activationLine;
748	        });
749	
750	        if (sectionAtActivationLine) {
751	            return sectionAtActivationLine.id;
752	        }
753	
754	        const nearestSection = sections
755	            .map((section) => ({
756	                id: section.id,
757	                distance: Math.abs(
758	                    section.element.getBoundingClientRect().top - activationLine
759	                ),
760	            }))
761	            .sort((a, b) => a.distance - b.distance)[0];
762	
763	        return nearestSection?.id ?? null;
764	    }
765	
766	    private getScrollRoot(): HTMLElement | null {
767	        return this.elementRef.nativeElement.closest(
768	            'main.workspace-content'
769	        ) as HTMLElement | null;
770	    }
771	
772	    private schedulePendingScrollTargetClear(
773	        scrollRoot: HTMLElement | null
774	    ): void {
775	        const clearPendingScrollTarget = () => {
776	            this.cancelPendingScrollTargetClear();
777	            this.settingsCtx.clearPendingScrollTarget();
778	        };
779	
780	        this.cancelPendingScrollTargetClear();
781	        this.pendingScrollClearTimer = window.setTimeout(
782	            clearPendingScrollTarget,
783	            SettingsComponent.PENDING_SCROLL_CLEAR_DELAY_MS
784	        );
785	        this.pendingScrollClearRoot = scrollRoot;
786	        this.pendingScrollEndListener = clearPendingScrollTarget;
787	        scrollRoot?.addEventListener?.('scrollend', clearPendingScrollTarget, {
788	            once: true,
789	        });
790	    }
791	
792	    private cancelPendingScrollTargetClear(): void {
793	        if (this.pendingScrollClearTimer) {
794	            clearTimeout(this.pendingScrollClearTimer);
795	            this.pendingScrollClearTimer = null;
796	        }
797	
798	        if (this.pendingScrollClearRoot && this.pendingScrollEndListener) {
799	            this.pendingScrollClearRoot.removeEventListener?.(
800	                'scrollend',
801	                this.pendingScrollEndListener
802	            );
803	        }
804	
805	        this.pendingScrollClearRoot = null;
806	        this.pendingScrollEndListener = null;
807	    }
808	
809	    private scrollToSection(sectionId: string): HTMLElement | null {
810	        const sectionElement = document.getElementById(sectionId);
811	        if (!sectionElement) {
812	            return null;
813	        }
814	
815	        const scrollRoot = this.getScrollRoot();
816	        if (!scrollRoot) {
817	            sectionElement.scrollIntoView({
818	                behavior: 'smooth',
819	                block: 'start',
820	            });
821	            return null;
822	        }
823	
824	        const rootRect = scrollRoot.getBoundingClientRect();
825	        const sectionRect = sectionElement.getBoundingClientRect();
826	        const sectionTop =
827	            scrollRoot.scrollTop + (sectionRect.top - rootRect.top);
828	        const sectionBottom = sectionTop + sectionRect.height;
829	        const visibleTop =
830	            scrollRoot.scrollTop + SettingsComponent.SECTION_SCROLL_TOP_GUTTER;
831	        const visibleBottom =
832	            scrollRoot.scrollTop +
833	            scrollRoot.clientHeight -
834	            SettingsComponent.SECTION_SCROLL_BOTTOM_GUTTER;
835	        let nextScrollTop = scrollRoot.scrollTop;
836	
837	        if (sectionTop < visibleTop) {
838	            nextScrollTop =
839	                sectionTop - SettingsComponent.SECTION_SCROLL_TOP_GUTTER;
840	        } else if (sectionBottom > visibleBottom) {
841	            nextScrollTop =
842	                sectionBottom -
843	                scrollRoot.clientHeight +
844	                SettingsComponent.SECTION_SCROLL_BOTTOM_GUTTER;
845	        }
846	
847	        const maxScrollTop = Math.max(
848	            0,
849	            scrollRoot.scrollHeight - scrollRoot.clientHeight
850	        );
851	
852	        scrollRoot.scrollTo({
853	            top: Math.min(Math.max(nextScrollTop, 0), maxScrollTop),
854	            behavior: 'smooth',
855	        });
856	
857	        return scrollRoot;
858	    }
859	
860	    private openSettingsSnackbar(
861	        message: string,
862	        config: MatSnackBarConfig = {}
863	    ): void {
864	        this.snackBar.open(message, undefined, {
865	            duration: 2000,
866	            horizontalPosition: 'center',
867	            verticalPosition: 'bottom',
868	            panelClass: ['settings-snackbar'],
869	            ...config,
870	        });
871	    }
872	}
