file.content:
:host {
    display: block;
    --settings-safe-bottom: env(safe-area-inset-bottom, 0px);
    --settings-action-bar-offset: 24px;
    --settings-action-bar-space: 112px;
    --settings-page-header-bg: color-mix(
        in srgb,
        var(--mat-sys-surface-container-low) 94%,
        rgba(255, 255, 255, 0.98)
    );
    --settings-page-header-border: color-mix(
        in srgb,
        var(--mat-sys-outline-variant) 72%,
        transparent
    );
    --settings-page-header-shadow:
        0 10px 20px -28px rgba(15, 23, 42, 0.16),
        0 1px 0 rgba(255, 255, 255, 0.68) inset;
    --settings-group-bg: color-mix(
        in srgb,
        var(--mat-sys-surface) 96%,
        rgba(255, 255, 255, 0.96)
    );
    --settings-group-border: color-mix(
        in srgb,
        var(--mat-sys-outline-variant) 78%,
        transparent
    );
    --settings-group-shadow: 0 14px 28px -32px rgba(15, 23, 42, 0.14);
    --settings-group-active-bg: color-mix(
        in srgb,
        var(--app-selection-color) 2%,
        rgba(255, 255, 255, 0.98)
    );
    --settings-group-active-ring: color-mix(
        in srgb,
        var(--app-selection-border) 68%,
        var(--settings-group-border)
    );
    --settings-group-active-glow: color-mix(
        in srgb,
        var(--app-selection-glow) 28%,
        transparent
    );
    --settings-group-active-shadow:
        inset 0 0 0 1px var(--settings-group-active-ring),
        0 12px 24px -28px var(--settings-group-active-glow);
    --settings-item-border: var(--app-separator);
    --settings-item-danger-bg: color-mix(
        in srgb,
        var(--mat-sys-error) 4%,
        rgba(255, 255, 255, 0.96)
    );
    --settings-item-danger-border: color-mix(
        in srgb,
        var(--mat-sys-error) 14%,
        transparent
    );
    --settings-action-bar-bg: color-mix(
        in srgb,
        var(--mat-sys-surface-container-low) 94%,
        rgba(255, 255, 255, 0.9)
    );
    --settings-action-bar-border: color-mix(
        in srgb,
        var(--mat-sys-outline-variant) 62%,
        transparent
    );
    --settings-action-bar-shadow: 0 10px 26px -26px rgba(15, 23, 42, 0.22);
    --settings-muted: color-mix(
        in srgb,
        var(--mat-sys-on-surface) 64%,
        transparent
    );
}

:host-context(.dark-theme),
:host-context([data-theme='dark']),
:host-context(.mat-app-background.dark) {
    --settings-page-header-bg: color-mix(
        in srgb,
        var(--mat-sys-surface-container) 92%,
        rgba(12, 16, 24, 0.94)
    );
    --settings-page-header-border: color-mix(
        in srgb,
        var(--mat-sys-outline-variant) 38%,
        transparent
    );
    --settings-page-header-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.05),
        0 16px 26px -34px rgba(0, 0, 0, 0.4);
    --settings-group-bg: color-mix(
        in srgb,
        var(--mat-sys-surface-container) 94%,
        rgba(10, 14, 22, 0.82)
    );
    --settings-group-border: rgba(255, 255, 255, 0.08);
    --settings-group-shadow: 0 16px 28px -32px rgba(0, 0, 0, 0.42);
    --settings-group-active-bg: color-mix(
        in srgb,
        var(--app-selection-surface) 24%,
        rgba(255, 255, 255, 0.015)
    );
    --settings-group-active-ring: color-mix(
        in srgb,
        var(--app-selection-border) 54%,
        rgba(255, 255, 255, 0.08)
    );
    --settings-group-active-glow: color-mix(
        in srgb,
        var(--app-selection-glow) 22%,
        transparent
    );
    --settings-group-active-shadow:
        inset 0 0 0 1px var(--settings-group-active-ring),
        0 10px 22px -28px var(--settings-group-active-glow);
    --settings-item-danger-bg: color-mix(
        in srgb,
        var(--mat-sys-error) 8%,
        rgba(24, 10, 12, 0.86)
    );
    --settings-item-danger-border: color-mix(
        in srgb,
        var(--mat-sys-error) 24%,
        transparent
    );
    --settings-action-bar-bg: color-mix(
        in srgb,
        var(--mat-sys-surface-container) 92%,
        transparent
    );
    --settings-action-bar-border: rgba(255, 255, 255, 0.08);
    --settings-action-bar-shadow: 0 8px 30px rgba(0, 0, 0, 0.18);
    --settings-muted: color-mix(
        in srgb,
        var(--mat-sys-on-surface) 68%,
        transparent
    );
}

.settings-container {
    height: auto;
    overflow: visible;
    padding: 18px 20px calc(36px + var(--settings-safe-bottom));
}

.settings-container.dialog-mode {
    height: auto;
    max-height: none;
    overflow: visible;
    padding: 12px 8px calc(24px + var(--settings-safe-bottom));
}

.settings-layout {
    display: flex;
    flex-direction: column;
    gap: 16px;
    align-items: stretch;
    max-width: 920px;
    margin: 0 auto;
    padding-bottom: calc(
        var(--settings-action-bar-space) + var(--settings-safe-bottom)
    );
}

.settings-container.dialog-mode .settings-layout {
    padding-bottom: 0;
}

.settings-page-header {
    padding: 14px 18px;
    border: 1px solid var(--settings-page-header-border);
    border-radius: 18px;
    background: var(--settings-page-header-bg);
    box-shadow: var(--settings-page-header-shadow);
}

.settings-page-header__text {
    max-width: 56ch;

    h1 {
        margin: 0;
        font-size: clamp(1.35rem, 2vw, 1.75rem);
        line-height: 1.08;
        letter-spacing: -0.03em;
        font-weight: 700;
    }

    p {
        margin: 4px 0 0;
        color: var(--settings-muted);
        font-size: 0.86rem;
        line-height: 1.45;
    }
}

.settings-content {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.settings-group {
    position: relative;
    background: var(--settings-group-bg);
    overflow: hidden;
    scroll-margin-top: 24px;
    padding: 0;
    border: 1px solid var(--settings-group-border);
    border-radius: 22px;
    box-shadow: var(--settings-group-shadow);
    transition:
        background 0.2s ease,
        box-shadow 0.2s ease,
        border-color 0.2s ease;
}

.settings-group--active {
    background: var(--settings-group-active-bg);
    border-color: var(--settings-group-active-ring);
    box-shadow: var(--settings-group-active-shadow);

    .settings-group__header-icon {
        background: color-mix(
            in srgb,
            var(--app-selection-surface-strong) 70%,
            var(--mat-sys-surface-container-high)
        );
        color: var(--app-selection-color);
        border-color: var(--settings-group-active-ring);
    }

    .settings-group__header-text h3 {
        color: var(--app-selection-color);
    }
}

.settings-group__header {
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 16px 18px 14px;

    .settings-group__header-icon {
        display: flex;
        align-items: center;
        justify-content: center;
        width: 40px;
        height: 40px;
        flex-shrink: 0;
        border: 1px solid color-mix(
            in srgb,
            var(--mat-sys-outline-variant) 74%,
            transparent
        );
        border-radius: 12px;
        background: color-mix(
            in srgb,
            var(--mat-sys-surface-container-high) 78%,
            transparent
        );
        color: var(--mat-sys-on-surface-variant);

        mat-icon {
            font-size: 20px;
            width: 20px;
            height: 20px;
        }
    }

    .settings-group__header-text {
        h3 {
            margin: 0;
            font-size: 1.08rem;
            font-weight: 700;
            letter-spacing: -0.02em;
        }

        p {
            margin: 2px 0 0;
            color: var(--settings-muted);
            font-size: 0.84rem;
            line-height: 1.45;
        }
    }
}

.settings-group__footer {
    padding: 12px 18px 16px;
    border-top: 1px solid var(--settings-item-border);
}

.setting-item {
    display: grid;
    grid-template-columns: minmax(0, 1.15fr) minmax(220px, 340px);
    gap: 14px;
    margin: 0 18px;
    padding: 14px 0;
    border-top: 1px solid var(--settings-item-border);
    background: transparent;

    &:last-of-type {
        margin-bottom: 0;
    }
}

.settings-group .setting-item:last-child {
    margin-bottom: 0;
}

.setting-item__meta {
    h4 {
        margin: 0;
        font-size: 0.95rem;
        font-weight: 650;
        letter-spacing: -0.01em;
    }

    p {
        margin: 3px 0 0;
        color: var(--settings-muted);
        font-size: 0.84rem;
        line-height: 1.45;
    }
}

.setting-item__control {
    display: flex;
    justify-content: flex-end;
    align-items: center;
    gap: 12px;
    min-height: 40px;

    mat-form-field,
    .w-full {
        width: min(100%, 340px);
    }
}

.setting-item__toggle {
    justify-content: flex-end;
}

.setting-item--full-control {
    grid-template-columns: 1fr;
    gap: 12px;
}

.setting-item--full-control .setting-item__control {
    justify-content: stretch;
}

.theme-switcher {
    width: min(100%, 540px);
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 8px;
}

.theme-switcher__option {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    min-height: 54px;
    padding: 12px 14px;
    border: 1px solid color-mix(
        in srgb,
        var(--mat-sys-outline-variant) 70%,
        transparent
    );
    border-radius: 16px;
    background: color-mix(
        in srgb,
        var(--mat-sys-surface-container-low) 88%,
        transparent
    );
    color: var(--mat-sys-on-surface-variant);
    font: inherit;
    font-size: 0.9rem;
    font-weight: 600;
    letter-spacing: -0.01em;
    cursor: pointer;
    transition:
        border-color 0.18s ease,
        background 0.18s ease,
        box-shadow 0.18s ease,
        color 0.18s ease;

    mat-icon {
        width: 18px;
        height: 18px;
        font-size: 18px;
    }

    &:hover {
        background: color-mix(
            in srgb,
            var(--mat-sys-surface-container-high) 86%,
            transparent
        );
        color: var(--mat-sys-on-surface);
    }

    &:focus-visible {
        outline: none;
        box-shadow: 0 0 0 3px
            color-mix(in srgb, var(--app-selection-color) 18%, transparent);
    }
}

.theme-switcher__option--selected {
    border-color: var(--settings-group-active-ring);
    background: linear-gradient(
        135deg,
        color-mix(
            in srgb,
            var(--app-selection-surface-strong) 72%,
            var(--mat-sys-surface-container-high)
        ),
        color-mix(
            in srgb,
            var(--app-selection-surface) 72%,
            var(--mat-sys-surface-container)
        )
    );
    color: var(--app-selection-color);
    box-shadow:
        inset 0 0 0 1px color-mix(
            in srgb,
            var(--app-selection-border) 54%,
            transparent
        ),
        0 10px 18px -22px var(--settings-group-active-glow);
}

.epg-sources {
    width: 100%;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.epg-source-row {
    display: flex;
    align-items: center;
    gap: 6px;

    .w-full {
        width: 100%;
    }
}

.inline-actions {
    display: flex;
    justify-content: flex-end;
    flex-wrap: wrap;
    gap: 6px;
}

.remote-control-urls {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 6px;
}

.remote-control-url-item {
    width: min(100%, 340px);
}

.url-row {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 4px;
}

.remote-control-url {
    font-family: 'JetBrains Mono', 'SFMono-Regular', Menlo, Monaco, Consolas, monospace;
    color: inherit;
    text-decoration: none;
    font-size: 0.84rem;

    &:hover {
        text-decoration: underline;
    }
}

.qr-code-container {
    display: flex;
    justify-content: flex-end;
    padding: 8px 0;
}

.version-block {
    flex-direction: column;
    align-items: flex-end;

    span {
        font-weight: 700;
    }

    small {
        margin-top: 4px;
        color: var(--mat-sys-on-surface-variant);
        text-align: right;
    }
}

.settings-note {
    margin: 12px 18px 18px;
    padding: 10px 12px;
    border-radius: 14px;
    font-size: 0.84rem;
    background: color-mix(in srgb, var(--mat-sys-primary) 8%, transparent);
    border: 1px solid color-mix(in srgb, var(--mat-sys-primary) 30%, transparent);
    line-height: 1.45;

    a {
        color: inherit;
        font-weight: 700;
    }
}

.danger-zone {
    margin-top: 8px;
    margin-bottom: 18px;
    padding: 14px 16px;
    background: var(--settings-item-danger-bg);
    border: 1px solid var(--settings-item-danger-border);
    border-radius: 16px;
}

.action-bar {
    position: sticky;
    bottom: calc(
        var(--settings-action-bar-offset) + var(--settings-safe-bottom)
    );
    margin-left: auto;
    z-index: 100;
    display: flex;
    justify-content: flex-end;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
    padding: 10px 14px;
    border: 1px solid var(--settings-action-bar-border);
    border-radius: 18px;
    background: var(--settings-action-bar-bg);
    backdrop-filter: blur(12px);
    box-shadow: var(--settings-action-bar-shadow);
}

.settings-container.dialog-mode .action-bar {
    position: static;
    margin-top: 12px;
    margin-bottom: 2px;
    box-shadow: none;
    border-radius: 16px;
    padding: 12px;
    justify-content: space-between;
}

@media (max-width: 1100px) {
    .settings-layout {
        max-width: 100%;
        padding: 0;
    }
}

@media (max-width: 860px) {
    .settings-container {
        height: auto;
        padding: 12px 12px calc(18px + var(--settings-safe-bottom));
    }

    .settings-page-header {
        padding: 12px 14px;
        border-radius: 16px;
    }

    .setting-item {
        grid-template-columns: 1fr;
        gap: 12px;
        margin: 0 14px;
        padding: 12px 0;
    }

    .setting-item__control {
        justify-content: flex-start;

        mat-form-field,
        .w-full,
        .epg-sources,
        .remote-control-url-item {
            width: 100%;
        }
    }

    .theme-switcher {
        width: 100%;
        grid-template-columns: 1fr;
    }

    .remote-control-urls,
    .version-block {
        align-items: flex-start;
    }

    .url-row {
        justify-content: flex-start;
        flex-wrap: wrap;
    }

    .action-bar {
        position: static;
        flex-direction: column-reverse;
        align-items: stretch;
        border-radius: 16px;
        box-shadow: none;
        width: 100%;
        margin-left: 0;

        button {
            width: 100%;
        }
    }
}

input.old_string:
.version-block {
    flex-direction: column;
    align-items: flex-end;

    span {
        font-weight: 700;
    }

    small {
        margin-top: 4px;
        color: var(--mat-sys-on-surface-variant);
        text-align: right;
    }
}

input.new_string:
.version-block {
    flex-direction: column;
    align-items: flex-end;

    span {
        font-weight: 700;
    }

    small {
        margin-top: 4px;
        color: var(--mat-sys-on-surface-variant);
        text-align: right;
    }
}

.link-cards {
    width: 100%;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 10px;
}

.link-card {
    display: grid;
    grid-template-columns: 40px minmax(0, 1fr) 20px;
    align-items: center;
    gap: 12px;
    padding: 12px 14px;
    border: 1px solid color-mix(
        in srgb,
        var(--mat-sys-outline-variant) 70%,
        transparent
    );
    border-radius: 16px;
    background: color-mix(
        in srgb,
        var(--mat-sys-surface-container-low) 88%,
        transparent
    );
    color: var(--mat-sys-on-surface);
    text-decoration: none;
    transition:
        border-color 0.18s ease,
        background 0.18s ease,
        transform 0.18s ease,
        box-shadow 0.18s ease;

    &:hover {
        transform: translateY(-1px);
        border-color: color-mix(
            in srgb,
            var(--app-selection-border) 54%,
            var(--mat-sys-outline-variant)
        );
        background: color-mix(
            in srgb,
            var(--mat-sys-surface-container-high) 92%,
            transparent
        );
        box-shadow: 0 10px 20px -22px rgba(15, 23, 42, 0.5);

        .link-card__arrow {
            opacity: 1;
            transform: translate(2px, -2px);
        }
    }

    &:focus-visible {
        outline: none;
        box-shadow:
            0 0 0 2px var(--mat-sys-surface),
            0 0 0 4px
                color-mix(in srgb, var(--app-selection-color) 40%, transparent);
    }
}

.link-card__glyph {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    border-radius: 12px;
    background: color-mix(
        in srgb,
        var(--mat-sys-surface-container-high) 82%,
        transparent
    );
    color: var(--mat-sys-on-surface-variant);

    svg {
        width: 20px;
        height: 20px;
    }

    mat-icon {
        font-size: 20px;
        width: 20px;
        height: 20px;
    }
}

.link-card--github .link-card__glyph {
    background: color-mix(
        in srgb,
        var(--mat-sys-on-surface) 10%,
        transparent
    );
    color: var(--mat-sys-on-surface);
}

.link-card--blog .link-card__glyph {
    background: color-mix(in srgb, #ff7849 18%, transparent);
    color: #ff8a5b;
}

.link-card--telegram .link-card__glyph {
    background: color-mix(in srgb, #229ed9 22%, transparent);
    color: #38b0e3;
}

.link-card__text {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 2px;

    strong {
        font-size: 0.92rem;
        font-weight: 650;
        letter-spacing: -0.01em;
    }

    span {
        color: var(--settings-muted);
        font-size: 0.78rem;
        line-height: 1.35;
        overflow: hidden;
        text-overflow: ellipsis;
        display: -webkit-box;
        -webkit-line-clamp: 2;
        -webkit-box-orient: vertical;
    }
}

.link-card__arrow {
    font-size: 18px;
    width: 18px;
    height: 18px;
    color: var(--settings-muted);
    opacity: 0.6;
    transition:
        opacity 0.18s ease,
        transform 0.18s ease;
}

.support-card {
    width: 100%;
    position: relative;
    display: flex;
    flex-direction: column;
    gap: 14px;
    padding: 18px;
    border-radius: 18px;
    border: 1px solid color-mix(in srgb, #ff4d6d 26%, transparent);
    background:
        radial-gradient(
            120% 140% at 0% 0%,
            color-mix(in srgb, #ff4d6d 16%, transparent) 0%,
            transparent 55%
        ),
        radial-gradient(
            120% 140% at 100% 100%,
            color-mix(in srgb, #ffb347 14%, transparent) 0%,
            transparent 60%
        ),
        color-mix(
            in srgb,
            var(--mat-sys-surface-container-low) 92%,
            transparent
        );
    overflow: hidden;

    &::after {
        content: '';
        position: absolute;
        inset: 0;
        pointer-events: none;
        background: radial-gradient(
            80% 100% at 50% -10%,
            color-mix(in srgb, #ff4d6d 12%, transparent) 0%,
            transparent 70%
        );
        opacity: 0.8;
    }
}

.support-card__intro {
    position: relative;
    display: flex;
    align-items: flex-start;
    gap: 14px;
    z-index: 1;
}

.support-card__emblem {
    flex: 0 0 auto;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    border-radius: 14px;
    background: linear-gradient(135deg, #ff4d6d, #ff8b5e);
    color: #fff;
    box-shadow:
        inset 0 1px 0 rgba(255, 255, 255, 0.35),
        0 10px 18px -10px rgba(255, 77, 109, 0.55);

    mat-icon {
        font-size: 22px;
        width: 22px;
        height: 22px;
    }
}

.support-card__copy {
    min-width: 0;
    flex: 1 1 auto;

    h4 {
        margin: 0;
        font-size: 1rem;
        font-weight: 700;
        letter-spacing: -0.01em;
    }

    p {
        margin: 4px 0 0;
        color: var(--settings-muted);
        font-size: 0.86rem;
        line-height: 1.5;
        max-width: 64ch;
    }
}

.support-card__actions {
    position: relative;
    z-index: 1;
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
}

.support-btn {
    flex: 1 1 220px;
    display: inline-flex;
    align-items: center;
    gap: 12px;
    padding: 10px 14px;
    border-radius: 14px;
    border: 1px solid transparent;
    text-decoration: none;
    color: #fff;
    transition:
        transform 0.18s ease,
        box-shadow 0.18s ease,
        filter 0.18s ease;

    &:hover {
        transform: translateY(-1px);
        filter: brightness(1.04);
    }

    &:focus-visible {
        outline: none;
        box-shadow:
